	access_idx, homepage_id, access_date, session_id, access_ip, referer_url, user_agent, access_cnt
) VALUES (
	STAT_COUNT_LOG_SEQ.NEXTVAL, #{homepage_id}, #{start_date}, #{session_id}, #{access_ip}, #{referer_url}, #{user_agent}, 1
)

