	access_idx, homepage_id, access_date, session_id, access_ip, referer_url, user_agent, access_cnt
FROM
	STATISTICS_COUNT_LOG
WHERE
	homepage_id = #{homepage_id}
AND	access_date = #{start_date}
AND	session_id = #{session_id}

